    public virtual void handleOrder(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        // {
        //     method: 'subscription',
        //     params: {
        //         channel: '130837.orders',
        //         data: [
        //             {
        //                 subaccount_id: 130837,
        //                 order_id: '1f44c564-5658-4b69-b8c4-4019924207d5',
        //                 instrument_name: 'BTC-PERP',
        //                 direction: 'buy',
        //                 label: 'test1234',
        //                 quote_id: null,
        //                 creation_timestamp: 1738578974146,
        //                 last_update_timestamp: 1738578974146,
        //                 limit_price: '10000',
        //                 amount: '0.01',
        //                 filled_amount: '0',
        //                 average_price: '0',
        //                 order_fee: '0',
        //                 order_type: 'limit',
        //                 time_in_force: 'post_only',
        //                 order_status: 'untriggered',
        //                 max_fee: '219',
        //                 signature_expiry_sec: 1746354973,
        //                 nonce: 1738578973570,
        //                 signer: '0x30CB7B06AdD6749BbE146A6827502B8f2a79269A',
        //                 signature: '0xc6927095f74a0d3b1aeef8c0579d120056530479f806e9d2e6616df742a8934c69046361beae833b32b25c0145e318438d7d1624bb835add956f63aa37192f571c',
        //                 cancel_reason: '',
        //                 mmp: false,
        //                 is_transfer: false,
        //                 replaced_order_id: null,
        //                 trigger_type: 'stoploss',
        //                 trigger_price_type: 'mark',
        //                 trigger_price: '102800',
        //                 trigger_reject_message: null
        //             }
        //         ]
        //     }
        // }
        //
        IDictionary<string, object> parameters = this.safeDict(message, "params");
        string? topic = this.safeString(parameters, "channel");
        List<object> rawOrders = this.safeList(parameters, "data", new List<object>() {});
        for (int i = 0; i < rawOrders.Count; i++)
        {
            object data = rawOrders[i];
            Dictionary<string, object> parsed = ccxt.BaseExchange.FromOrder(this.parseOrder(data));
            string? symbol = this.safeString(parsed, "symbol");
            string? orderId = this.safeString(parsed, "id");
            if ((symbol != null))
            {
                if ((this.orders == null))
                {
                    Int64? limit = this.safeInteger(this.options, "ordersLimit", 1000);
                    this.orders = new ArrayCacheBySymbolById(limit);
                }
                ccxt.pro.ArrayCache cachedOrders = this.orders;
                IDictionary<string, object> orders = this.safeDict((cachedOrders as ArrayCache).hashmap, symbol, new Dictionary<string, object>() {});
                IDictionary<string, object> order = ((orderId == null)) ? null : this.safeDict(orders, orderId);
                if ((order != null))
                {
                    IDictionary<string, object> fee = this.safeDict(order, "fee");
                    if ((fee != null))
                    {
                        parsed["fee"] = fee;
                    }
                    List<object> fees = this.safeList(order, "fees");
                    if ((fees != null))
                    {
                        parsed["fees"] = fees;
                    }
                    parsed["trades"] = this.safeList(order, "trades");
                    parsed["timestamp"] = this.safeInteger(order, "timestamp");
                    parsed["datetime"] = this.safeString(order, "datetime");
                }
                cachedOrders.append(parsed);
                if ((topic != null))
                {
                    string messageHashSymbol = ((topic + ":") + symbol);
                    client.resolve(this.orders, messageHashSymbol);
                }
            }
        }
        client.resolve(this.orders, topic);
    }

